using System.Collections.Generic;
using System.Linq;
using Astrea.DailyRun;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "DraftDiceRunModifier", menuName = "Data/RunModifiers/DraftDiceRunModifier", order = 0)]
public class DraftDiceRunModifier : RunModifier
{
	public enum DraftDiceRunModifierType
	{
		TheChosenPool,
		CustomizedOpening,
		SealedPool
	}

	[Header("Spcecifics")]
	[SerializeField]
	private PlayerDiceInventoryData dicePool;

	[SerializeField]
	private DraftDiceRunModifierType draftDiceRunModifierType;

	[SerializeField]
	[ShowIf("IsTheChosenPool")]
	private ClearingReward rewardToChangeOnMap;

	[SerializeField]
	[HideIf("isSealedPool")]
	private DiceReward diceReward;

	[SerializeField]
	[HideIf("isSealedPool")]
	private List<DiceReward> diceRewardsToRemove = new List<DiceReward>();

	[SerializeField]
	[HideIf("isSealedPoolOrCustomizedOpening")]
	private DiceReward epicDiceReward;

	[SerializeField]
	[HideIf("isSealedPool")]
	private ClearingReward draftDiceClearingReward;

	[SerializeField]
	[ShowIf("isSealedPool")]
	private ClearingReward sealedPoolClearing;

	[SerializeField]
	[ShowIf("isSealedPool")]
	private DailyRunHandler dailyRunHandler;

	[SerializeField]
	[ShowIf("isSealedPool")]
	private PlayerDiceInventoryData playerAllDiceTemporary;

	[SerializeField]
	[ShowIf("isSealedPool")]
	private PlayerDiceInventoryData drawPool;

	[SerializeField]
	[ShowIf("isSealedPool")]
	private PlayerDiceInventoryData discard;

	public DraftDiceRunModifierType DraftDiceRunModifierTypeEnum => draftDiceRunModifierType;

	public bool IsTheChosenPool => draftDiceRunModifierType == DraftDiceRunModifierType.TheChosenPool;

	private bool isSealedPool => draftDiceRunModifierType == DraftDiceRunModifierType.SealedPool;

	public bool IsCustomizedOpening => draftDiceRunModifierType == DraftDiceRunModifierType.CustomizedOpening;

	private bool isSealedPoolOrCustomizedOpening
	{
		get
		{
			if (!isSealedPool)
			{
				return IsCustomizedOpening;
			}
			return true;
		}
	}

	public ClearingReward RewardToChangeOnMap => rewardToChangeOnMap;

	public override void Initialize()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.DraftDiceRunModifier = this;
		if (ReferenceSingleton<AssetsReference>.Instance.GameController.IsNewRun)
		{
			ReferenceSingleton<AssetsReference>.Instance.SaveSystem.SaveDiceAlreadyDraftedStartOfTheRun(value: false);
		}
	}

	public void StartDraftingDice()
	{
		if (isSealedPool)
		{
			sealedPoolClearing.ResetRewardsCounter();
			drawPool.ClearAllDices();
			discard.ClearAllDices();
		}
		else
		{
			draftDiceClearingReward.ResetRewardsCounter();
		}
		RandomUtilities.SetUnityEngineRandomInitStateSeed(ReferenceSingleton<AssetsReference>.Instance.MapHandler.GetSeedWithCurrentMapPlayerTracker());
		if ((bool)ReferenceSingleton<RunModifiersManager>.Instance.ReliableEightRunModifier)
		{
			if (ReferenceSingleton<AssetsReference>.Instance.GameController.IsNewRun)
			{
				Dice diceAddedToPool = ReferenceSingleton<RunModifiersManager>.Instance.ReliableEightRunModifier.DiceAddedToPool;
				dicePool.RemoveAllButDice(diceAddedToPool);
				int diceAmount = dicePool.GetDiceAmount(diceAddedToPool);
				if (diceAmount > 8)
				{
					dicePool.DecreaseDiceAmount(diceAddedToPool, diceAmount - 8);
				}
				ReferenceSingleton<AssetsReference>.Instance.SaveSystem.SaveDiceInventory();
				ReferenceSingleton<AssetsReference>.Instance.SaveSystem.StoreCachedFile();
			}
		}
		else
		{
			dicePool.ClearAllDices();
		}
		ReferenceSingleton<AssetsReference>.Instance.MapHandler.SetBattleSceneSetupToReward();
		OnlySpecificChestRunModifier onlySpecificChestRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.OnlySpecificChestRunModifier;
		if (isSealedPool)
		{
			playerAllDiceTemporary.ClearAllDices();
			for (int i = 0; i < runModifierVariableAmount; i++)
			{
				DiceTier diceTierToPick = null;
				if (onlySpecificChestRunModifier != null)
				{
					diceTierToPick = (onlySpecificChestRunModifier.DiceClearingReward.Rewards.First() as DiceReward).DiceTiers.First();
				}
				Dice randomDiceWithRandomChanceOfBeingCharacterDice = dailyRunHandler.GetRandomDiceWithRandomChanceOfBeingCharacterDice(diceTierToPick);
				playerAllDiceTemporary.IncreaseDiceAmount(randomDiceWithRandomChanceOfBeingCharacterDice, 1, insertAsFirst: false, updateDicePoolText: false);
			}
			ReferenceSingleton<AssetsReference>.Instance.MapHandler.SetClearingReward(sealedPoolClearing);
		}
		else
		{
			DiceReward item = diceReward;
			if (onlySpecificChestRunModifier != null)
			{
				item = onlySpecificChestRunModifier.DiceClearingReward.Rewards.First() as DiceReward;
			}
			List<Reward> list = new List<Reward>();
			for (int j = 0; j < runModifierVariableAmount; j++)
			{
				list.Add(item);
			}
			draftDiceClearingReward.SetRewards(list.ToArray());
			ReferenceSingleton<AssetsReference>.Instance.MapHandler.SetClearingReward(draftDiceClearingReward);
		}
	}

	public void EndedDraftingDice()
	{
		ReferenceSingleton<AssetsReference>.Instance.SaveSystem.SaveDiceAlreadyDraftedStartOfTheRun(value: true);
	}

	public Reward[] GetBattleModifiedRewards(Reward[] nonModifiedRewards)
	{
		List<Reward> list = nonModifiedRewards.DuplicateAsList();
		bool flag = false;
		for (int i = 0; i < diceRewardsToRemove.Count; i++)
		{
			if (list.Contains(diceRewardsToRemove[i]))
			{
				flag = true;
			}
		}
		if (!ReferenceSingleton<AssetsReference>.Instance.MapHandler.BossBattle && list.Contains(epicDiceReward))
		{
			flag = true;
		}
		if (!flag)
		{
			return nonModifiedRewards;
		}
		if (!ReferenceSingleton<AssetsReference>.Instance.MapHandler.BossBattle && list.Contains(epicDiceReward))
		{
			list.RemoveAll((Reward item) => item == epicDiceReward);
		}
		list.RemoveAll((Reward item) => diceRewardsToRemove.Contains(item));
		return list.ToArray();
	}
}
